/**
 * The component catalog, typed for the browser.
 *
 * `catalog.json` is generated by `scripts/generate-agent-catalog.mjs` from the
 * same three sources the backend uses (the public component metadata, the
 * measured pin map and the wiring rule file), so the agent in the browser and
 * the agent on the server can never disagree about which parts exist, what
 * their pins are called, or which properties a patch may touch.
 *
 * Nothing here is hand-maintained per part. When a new component is added to
 * the canvas, it appears here as soon as the generator runs — which is also
 * what the pin-drift test in `src/agent/__tests__/catalog.test.ts` enforces.
 */
import raw from './catalog.json';

export interface PinVariant {
  when: Record<string, string>;
  pins: string[];
}

export interface SignalRule {
  cap: string;
  dir?: 'in' | 'out' | 'bidir';
  optional?: boolean;
  severity?: string;
}

export interface BusRule {
  type: string;
  pins: Record<string, string>;
  optional?: boolean;
  when?: Record<string, string>;
}

export interface PartSpec {
  name: string;
  tag: string;
  category: string;
  class: string;
  pins: string[];
  pinVariants?: PinVariant[];
  properties: string[];
  defaults: Record<string, string | number | boolean>;
  placeable: boolean;
  sim: boolean;
  tags: string[];
  description?: string;
  why?: string;
  notes?: string;
  power?: Record<string, 'supply' | 'ground'>;
  signal?: Record<string, SignalRule>;
  bus?: BusRule[];
  libraries?: string[];
  interactions?: string[];
  stimulusKeys?: string[];
  [key: string]: unknown;
}

export interface BoardSpec {
  label: string;
  fqbn: string | null;
  kind: string;
  family?: string;
  pins: string[];
  pwm: number[];
  analog: string[];
  serial: string[];
  i2c: Record<string, string>;
  spi: Record<string, string>;
  uart: Record<string, string>;
  vcc: number;
  max_pin_ma: number;
}

interface CatalogFile {
  version: number;
  boards: Record<string, BoardSpec>;
  boardCoreHeaders?: Record<string, string[]>;
  boardCoreHeadersByBoard?: Record<string, string[]>;
  severity: Record<string, string>;
  runtimeProperties: { global: string[]; parts: Record<string, string[]> };
  parts: Record<string, PartSpec>;
}

export const catalog = raw as unknown as CatalogFile;
export const PARTS: Record<string, PartSpec> = catalog.parts;
export const BOARD: BoardSpec = catalog.boards['arduino-uno'];

// NOTE: keep identical to _BOARD_ALIASES in backend/app/agent/catalog.py.
// All keys are lowercase: lookup lowercases the input first.
const BOARD_ALIASES: Record<string, string> = {
  uno: 'arduino-uno',
  'uno-r3': 'arduino-uno',
  'arduino-uno-r3': 'arduino-uno',
  'arduino uno': 'arduino-uno',
  nano: 'arduino-nano',
  'arduino nano': 'arduino-nano',
  mega: 'arduino-mega',
  mega2560: 'arduino-mega',
  'mega-2560': 'arduino-mega',
  'arduino-mega-2560': 'arduino-mega',
  'arduino mega': 'arduino-mega',
  esp32dev: 'esp32',
  esp32devkit: 'esp32',
  'esp32-devkit': 'esp32',
  'esp32-devkit-v1': 'esp32',
  'esp32-wroom': 'esp32',
  'esp32-wroom-32': 'esp32',
  lolin32: 'wemos-lolin32-lite',
  pico: 'raspberry-pi-pico',
  'pi-pico': 'raspberry-pi-pico',
  rpipico: 'raspberry-pi-pico',
  rp2040: 'raspberry-pi-pico',
  picow: 'pi-pico-w',
  'pico-w': 'pi-pico-w',
  rpipicow: 'pi-pico-w',
  'raspberry-pi-pico-w': 'pi-pico-w',
  'nano-esp32': 'arduino-nano-esp32',
  'xiao-s3': 'xiao-esp32-s3',
  'esp32-s3-devkit': 'esp32-s3',
  'xiao-c3': 'xiao-esp32-c3',
  'esp32-c3-devkit': 'esp32-c3',
  supermini: 'aitewinrobot-esp32c3-supermini',
  bluepill: 'stm32-bluepill',
  blackpill: 'stm32-blackpill',
  attiny: 'attiny85',
};

/** Canonical board kind shared with backend Board normalization. */
export function normalizeBoardKind(value: string | undefined): string | undefined {
  if (!value) return undefined;
  // Mirror backend normalize_board_kind exactly: strip whitespace, accept an
  // exact catalog id (case-insensitively — catalog ids are all lowercase),
  // else resolve the short aliases, else retry with underscores as hyphens.
  const raw = value.trim();
  if (!raw) return undefined;
  if (Object.prototype.hasOwnProperty.call(catalog.boards, raw)) return raw;
  const lowered = raw.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(catalog.boards, lowered)) return lowered;
  const direct = BOARD_ALIASES[lowered];
  if (direct) return direct;
  const hyphenated = lowered.replace(/_/g, '-');
  if (Object.prototype.hasOwnProperty.call(catalog.boards, hyphenated)) return hyphenated;
  return BOARD_ALIASES[hyphenated];
}

/** Every part a patch may place, sorted by id. */
export const PLACEABLE_IDS: string[] = Object.entries(PARTS)
  .filter(([, spec]) => spec.placeable)
  .map(([id]) => id)
  .sort();

/** Total parts the canvas knows about (placeable or not). */
export const CATALOG_SIZE = Object.keys(PARTS).length;
export const PLACEABLE_SIZE = PLACEABLE_IDS.length;

const RUNTIME_GLOBAL = new Set(catalog.runtimeProperties.global);

export function partSpec(id: string): PartSpec | undefined {
  return PARTS[id];
}

export function isPlaceable(id: string): boolean {
  return PARTS[id]?.placeable === true;
}

/** Properties a patch may set — the catalog's editable list for the part. */
export function editableProperties(id: string): string[] {
  return PARTS[id]?.properties ?? [];
}

/** Properties the canvas owns at runtime and a patch must never set. */
export function runtimePropertiesFor(id: string): Set<string> {
  return new Set([...RUNTIME_GLOBAL, ...(catalog.runtimeProperties.parts[id] ?? [])]);
}

/** Pins for an instance, honouring property-driven variants (digits=4, pins=i2c). */
export function pinsFor(id: string, properties: Record<string, unknown> = {}): string[] {
  const spec = PARTS[id];
  if (!spec) return [];
  for (const variant of spec.pinVariants ?? []) {
    const matches = Object.entries(variant.when).every(
      ([key, value]) => String(properties[key] ?? '') === String(value),
    );
    if (matches) return variant.pins;
  }
  return spec.pins;
}

/** Interactions the runtime can actually drive for this part. */
export function interactionsFor(id: string): string[] {
  return PARTS[id]?.interactions ?? [];
}
